#include <stdio.h>

long long add_bonus(long long score, int levels) {
    return score + 100LL * levels;
}

int main(void) {
    long long score;
    int levels;
    scanf("%lld %d", &score, &levels);
    score = add_bonus(score, levels);
    printf("%lld\n", score);
